sql.where:
pi.deleted = 0



    AND pi.institution_id = #{reqVO.institutionId}


    AND pi.institution_type_id = #{reqVO.institutionTypeId}


    AND pi.area_code = #{reqVO.areaCode}


    AND pi.manager_id = #{reqVO.managerId}


    AND pi.operation_status_id = #{reqVO.operationStatusId}




    AND pi.cleaning_standard = #{reqVO.cleaningStandard}


    AND pi.cleaning_frequency = #{reqVO.cleaningFrequency}


    AND pi.cleaning_time = #{reqVO.cleaningTime}


    AND pi.responsibility_area = #{reqVO.responsibilityArea}




    AND pi.name LIKE CONCAT('%', #{reqVO.name}, '%')


    AND pi.address LIKE CONCAT('%', #{reqVO.address}, '%')


    AND pi.cleaner_ids LIKE CONCAT('%', #{reqVO.cleanerIds}, '%')
